  const wall = (x, z, ww, dd, h = H, y = 0) => { w.add('w', G.box(), wc, x, y, z, 0, 0, 0, ww, h, dd); w.solid(x - ww / 2, y, z - dd / 2, x + ww / 2, y + h, z + dd / 2); };
  wall(IX, z0 - 0.15, W + 0.6, 0.3); wall(x0 - 0.15, IZ, 0.3, D); wall(x1 + 0.15, IZ, 0.3, D); const dg = o.doorW || 2.4; wall(IX - (W + dg) / 4 - 0.15, z1 + 0.15, (W - dg) / 2 + 0.3, 0.3); wall(IX + (W + dg) / 4 + 0.15, z1 + 0.15, (W - dg) / 2 + 0.3, 0.3); w.add('w', G.box(), wc, IX, 2.8, z1 + 0.15, 0, 0, 0, dg, H - 2.8, 0.3); w.solid(IX - dg / 2, 2.8, z1, IX + dg / 2, H, z1 + 0.3);
